const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Dry Chaco region (approximate bounding box)
  const dryChaco = ee.Geometry.Polygon([
    [[-63.5, -19.5], [-57.5, -19.5], [-57.5, -26.5], [-63.5, -26.5], [-63.5, -19.5]]
  ]);

  // 2. Load Hansen Global Forest Change dataset
  const gfc = ee.Image('UMD/hansen/global_forest_change_2019_v1_7');

  // 3. Get tree cover for 2000 and loss up to 2019
  const treeCover2000 = gfc.select('treecover2000');  // Tree cover percentage in 2000
  const loss = gfc.select('loss');  // Loss pixels (1=loss, 0=no loss)

  // Create mask for loss up to 2019 (all loss years 2001-2019)
  const lossMask = loss.eq(0);  // 1 where no loss (still forest)

  // Forest cover for 2019: areas that were forest in 2000 AND didn't experience loss
  // Apply 30% tree cover threshold for forest definition
  const forest2000 = treeCover2000.gte(30);
  const forest2019 = forest2000.updateMask(lossMask);

  // 4. Calculate forest area in square kilometers for both years
  const areaImage = ee.Image.pixelArea().divide(1000000);  // Convert m² to km²

  const forestArea2000 = forest2000.multiply(areaImage);
  const forestArea2019 = forest2019.multiply(areaImage);

  // 5. Compute total area for the region
  const reducer = ee.Reducer.sum();

  const stats2000 = forestArea2000.reduceRegion({
    reducer: reducer,
    geometry: dryChaco,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = forestArea2019.reduceRegion({
    reducer: reducer,
    geometry: dryChaco,
    scale: 1000,
    maxPixels: 1e9
  });

  const area2000 = stats2000.get('treecover2000').getInfo();
  const area2019 = stats2019.get('treecover2000').getInfo();

  // 6. Check for data issues
  if (area2000 === null || area2019 === null) {
    console.log("Calculation failed - null results");
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Calculate percentage change
  const percentageChange = ((area2000 - area2019) / area2000) * 100;

  // 8. Output stats
  console.log(`2000 Forest Area: ${area2000.toFixed(0)} km²`);
  console.log(`2019 Forest Area: ${area2019.toFixed(0)} km²`);
  console.log(`Forest Loss: ${(area2000 - area2019).toFixed(0)} km²`);
  console.log(`Percentage Change: ${percentageChange.toFixed(1)}%`);

  // 9. Determine answer
  if (percentageChange > 10) {
    console.log("<answer>A</answer>");  // Yes, decreased by more than 10%
  } else {
    console.log("<answer>B</answer>");  // No, didn't decrease by more than 10%
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
